import{_ as t,o,c as a,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Lab 5 · State machines and time","description":"","frontmatter":{},"headers":[],"relativePath":"labs/lab-5-state-machines-and-time.md","filePath":"labs/lab-5-state-machines-and-time.md","lastUpdated":null}'),r={name:"labs/lab-5-state-machines-and-time.md"};function s(i,e,h,l,c,d){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="lab-5-·-state-machines-and-time" tabindex="-1">Lab 5 · State machines and time <a class="header-anchor" href="#lab-5-·-state-machines-and-time" aria-label="Permalink to &quot;Lab 5 · State machines and time&quot;">​</a></h1><p><strong>Deliverable:</strong> a pull request: the governance interface, done properly · <strong>Time:</strong> two hours</p><p>A governance proposal moves through eight states, three of them on timers, and two of the transitions need somebody to push a button. The contract handles this correctly. The interface currently does not, and the gap between them is where most dApp bugs live.</p><h2 id="the-job" tabindex="-1">The job <a class="header-anchor" href="#the-job" aria-label="Permalink to &quot;The job&quot;">​</a></h2><p>Rebuild the module 12 part of the Council card so a resident who has never used a DAO can follow a proposal from creation to execution without asking anyone what is going on.</p><h2 id="the-specification" tabindex="-1">The specification <a class="header-anchor" href="#the-specification" aria-label="Permalink to &quot;The specification&quot;">​</a></h2><p><strong>Show the state, and what it means.</strong> <code>Pending</code>, <code>Active</code>, <code>Succeeded</code>, <code>Defeated</code>, <code>Queued</code>, <code>Executed</code>, <code>Canceled</code>, <code>Expired</code>. Each with a sentence. &quot;Succeeded&quot; does not tell a user the money has not moved yet.</p><p><strong>Show the clock.</strong> Pending and Active end at a known time; a queued proposal becomes executable at a known time. Count down, live, and say what happens when the countdown reaches zero.</p><p><strong>Show the vote.</strong> For and against, as a bar. Quorum as progress toward a threshold, not a raw number — 4% of supply means nothing to a reader without the denominator.</p><p><strong>Show what the proposal does.</strong> Right now a proposal is a description string. Decode the call: this proposal sends <em>N TVD</em> to <em>0x…</em>. A governance interface that cannot tell a voter what they are voting for is a governance interface in name only.</p><p><strong>Fix the description problem.</strong> Only the <em>hash</em> of the description is on chain, and queuing and executing need the exact original text. Today the UI asks the user to paste it and keeps a copy in <code>localStorage</code> — so a proposal created in one browser cannot be queued in another, which for a DAO is a real failure.</p><p>Recover the text from the <code>ProposalCreated</code> event log, with the local copy as a fallback rather than the source of truth. Then nobody has to paste anything.</p><p><strong>Guide the next action.</strong> At every state, exactly one thing is worth doing: wait, vote, queue, execute. Show that one thing. Anything else should be absent, not disabled without explanation.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>[ ] All eight states render, each with a sentence a non-expert understands.</li><li>[ ] Countdowns update live and are correct against <strong>block time</strong>, not the browser clock.</li><li>[ ] Quorum shown as progress toward the requirement, with the requirement visible.</li><li>[ ] Each proposal shows the decoded action: recipient and amount.</li><li>[ ] Queue and execute work <strong>in a fresh browser with empty local storage</strong>. A reviewer will test exactly this.</li><li>[ ] A user who has not delegated sees a clear warning that their tokens do not vote.</li><li>[ ] A user who was not delegated at the snapshot sees why they cannot vote — and it says snapshot, not &quot;no tokens&quot;, because those are different problems.</li><li>[ ] All failure states handled as in lab 3.</li><li>[ ] CI green.</li></ul><h2 id="technical-requirements" tabindex="-1">Technical requirements <a class="header-anchor" href="#technical-requirements" aria-label="Permalink to &quot;Technical requirements&quot;">​</a></h2><p><strong>Block time, not wall time.</strong> The chain&#39;s clock is what the contract uses. On a local chain where you have time-travelled, the two are hours apart. Read the latest block&#39;s timestamp and derive your countdowns from it, or your interface will confidently show the wrong number.</p><p><strong>The event log is the source of truth</strong> for the description. <code>localStorage</code> is a cache and should be labelled as one in the code.</p><p><strong>Decode the calldata</strong> with viem&#39;s <code>decodeFunctionData</code> against the TownToken ABI. Handle a proposal whose calldata you cannot decode — show it as raw rather than crashing, because one day somebody will propose something your UI has never seen.</p><h2 id="the-question-to-answer-in-your-pr" tabindex="-1">The question to answer in your PR <a class="header-anchor" href="#the-question-to-answer-in-your-pr" aria-label="Permalink to &quot;The question to answer in your PR&quot;">​</a></h2><p>The Council&#39;s timings are one minute, ten minutes, two minutes — so a class can watch a whole cycle. Real DAOs use days and weeks.</p><p><strong>What in your interface would break if the voting period were seven days?</strong> Countdowns rendered in seconds, a page that must stay open, a poll that runs every second for a week. Name the specific things, and say which you would change.</p><h2 id="common-ways-this-goes-wrong" tabindex="-1">Common ways this goes wrong <a class="header-anchor" href="#common-ways-this-goes-wrong" aria-label="Permalink to &quot;Common ways this goes wrong&quot;">​</a></h2><ul><li><strong><code>Date.now()</code> for countdowns.</strong> Correct in the demo, wrong on any chain whose clock has drifted or been warped.</li><li><strong>Storing the description only locally.</strong> The bug you were asked to fix. A reviewer will open a private window.</li><li><strong>Hiding the snapshot rule.</strong> A user who wrapped after the proposal opened will be confused and then angry. Explain it before they try.</li><li><strong>A timer per proposal, never cleaned up.</strong> Ten proposals, ten intervals, none cleared on unmount.</li><li><strong>Rounding quorum to zero.</strong> Small numbers with 18 decimals round badly. Check the edges.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>No contract changes — the Governor and Timelock stay exactly as deployed. The multisig half of the card is not part of this lab.</p><h2 id="hand-in" tabindex="-1">Hand in <a class="header-anchor" href="#hand-in" aria-label="Permalink to &quot;Hand in&quot;">​</a></h2><ol><li>The PR, CI green, reviewed and approved.</li><li>Your review of someone else&#39;s PR. Open their branch in a <strong>private window</strong>, with no local storage, and try to queue a proposal somebody else created. That one test finds the bug this lab exists to fix.</li><li>An incident write-up if anything broke.</li></ol>',28)])])}const g=t(r,[["render",s]]);export{p as __pageData,g as default};
